/* @lc app=leetcode id=1735 lang=kotlin */ class Solution { fun fac(k: Int): List<Int> = (2..Math.sqrt(k.toDouble()).toInt()).fold(k to listOf<Int>()) { (r, es), p -> if (r % p != 0) r to es else generateSequence(r to 0) { (x, c) -> if (x % p == 0) x / p to c + 1 else null }.last().let { (x, c) -> x to es + c } }.let { (r, es) -> if (r > 1) es + 1 else es } fun waysToFillArray(queries: Array<IntArray>): IntArray = queries.map { (n, k) -> fac(k).fold(java.math.BigInteger.ONE) { r, e -> r * (1..e).fold(java.math.BigInteger.ONE) { c, i -> c * (n - 1 + i).toBigInteger() / i.toBigInteger() } }.mod(java.math.BigInteger.valueOf(1_000_000_007)).toInt() }.toIntArray() }